import {createSandboxInvoicePdf} from "../../demo/sandbox-invoice-pdf";
import {DEMO_ORG_ID} from "../../demo/scenarios";

/**
 * Hackathon-only, exact-byte AI test exception.
 *
 * Only ONE invoice generated by MandateGate itself can be observed without
 * full provider ZDR on the payment-capable Sandbox host. Other sources still
 * use strict /observe. The model observation is T1 and never pays.
 */
const DEMO_RENDER_SERVICE_ID="srv-db39vmm7bikc73c55nh0";
const PAYPAL_SANDBOX_URL="https://api-m.sandbox.paypal.com";

export function sandboxInvoiceNonZdrEnvironmentEnabled():boolean{
  return process.env.RENDER_SERVICE_ID===DEMO_RENDER_SERVICE_ID &&
    process.env.MANDATEGATE_RUNTIME_MODE==="neon-sandbox" &&
    process.env.MANDATEGATE_SANDBOX_VERIFIED_INVOICE_DEMO==="1" &&
    process.env.MANDATEGATE_ENABLE_INVOICE_AI==="1" &&
    process.env.MANDATEGATE_DISABLE_PAYMENTS==="0" &&
    process.env.PAYPAL_BASE_URL===PAYPAL_SANDBOX_URL &&
    typeof process.env.DEMO_PAYPAL_RECEIVER_EMAIL==="string";
}
function sandboxFixtureSha256():string|null{
  if(!sandboxInvoiceNonZdrEnvironmentEnabled())return null;
  try{
    return createSandboxInvoicePdf(process.env.DEMO_PAYPAL_RECEIVER_EMAIL!).sha256;
  }catch{return null;}
}
function historicalSyntheticTestEnvironmentEnabled():boolean{
  const localUrl=process.env.BETTER_AUTH_URL??"";
  const localDev=process.env.NODE_ENV!=="production" &&
    (localUrl==="http://127.0.0.1:3000"||localUrl==="http://localhost:3000");
  const boundDemoService=process.env.RENDER_SERVICE_ID===DEMO_RENDER_SERVICE_ID;
  return process.env.MANDATEGATE_DEPLOYMENT_ROLE==="demo" &&
    process.env.MANDATEGATE_SYNTHETIC_NON_ZDR_TEST==="1" &&
    process.env.PAYPAL_BASE_URL===PAYPAL_SANDBOX_URL &&
    (localDev||boundDemoService);
}
export function syntheticNonZdrTestEnvironmentEnabled():boolean{
  return historicalSyntheticTestEnvironmentEnabled() ||
    sandboxFixtureSha256()!==null;
}
export function isExactSandboxPdfNonZdrSource(input:{
  organizationId:string; mimeType:string; sha256:string;
}):boolean{
  const sha=sandboxFixtureSha256();
  return sha!==null && input.organizationId===DEMO_ORG_ID &&
    input.mimeType==="application/pdf" && input.sha256===sha;
}
export function isSyntheticNonZdrSourceAllowlisted(sha256:string):boolean{
  if(!/^[a-f0-9]{64}$/.test(sha256))return false;
  const exactSandbox=sandboxFixtureSha256();
  if(exactSandbox!==null){
    // The payout-capable Sandbox never honors arbitrary env SHA allowlists.
    return sha256===exactSandbox;
  }
  if(!historicalSyntheticTestEnvironmentEnabled())return false;
  return (process.env.MANDATEGATE_SYNTHETIC_NON_ZDR_SOURCE_SHA256_ALLOWLIST??"")
    .split(",").some(value=>value.trim()===sha256);
}
